'use client';

import { useMemo, useState } from 'react';
import {
  Activity, ArrowUpRight, Bell, CalendarDays, Check, ChevronDown, CircleDollarSign,
  Clock3, FileText, Filter, LayoutDashboard, Menu, Plus, Search, Settings,
  Sparkles, Target, Users, X, Zap,
} from 'lucide-react';
import { importedArtists, importedClients } from './imported-data';

type Section = 'Mi día' | 'Clientes' | 'Pipeline' | 'Eventos' | 'Talento' | 'Tareas' | 'Propuestas';
type EventHealth = 'green' | 'orange' | 'red';

const nav: { label: Section; icon: typeof LayoutDashboard }[] = [
  { label: 'Mi día', icon: LayoutDashboard },
  { label: 'Clientes', icon: Users },
  { label: 'Pipeline', icon: Target },
  { label: 'Eventos', icon: CalendarDays },
  { label: 'Talento', icon: Sparkles },
  { label: 'Tareas', icon: Check },
  { label: 'Propuestas', icon: FileText },
];

const events = [
  { id: 'EV-2048', title: 'Lanzamiento Aurora', client: 'Northstar Events', date: '18 SEP', time: '20:30', city: 'Barcelona', venue: 'Casa Bonay', status: 'Producción', health: 'green' as EventHealth, artists: 6, issue: 'Todo listo' },
  { id: 'EV-2051', title: 'Boda de Clara & Hugo', client: 'Naranja Weddings', date: '21 SEP', time: '18:00', city: 'Valencia', venue: 'La Cartuja', status: 'Confirmado', health: 'orange' as EventHealth, artists: 4, issue: 'Falta confirmar timing' },
  { id: 'EV-2057', title: 'Afterwork Meliá', client: 'Meliá Hotels', date: '26 SEP', time: '19:30', city: 'Madrid', venue: 'Gran Vía 42', status: 'Propuesta', health: 'red' as EventHealth, artists: 0, issue: 'Depósito pendiente' },
];

const pipeline = [
  { label: 'Nuevo lead', color: '#8a8f9c', count: 8, value: '24.800 €', cards: ['Studio 54 Agency', 'Bridal Lab'] },
  { label: 'Contactado', color: '#b18cff', count: 5, value: '18.200 €', cards: ['Naranja Weddings', 'Hotel Miramar'] },
  { label: 'Propuesta', color: '#f5b84b', count: 3, value: '31.600 €', cards: ['Meliá Hotels', 'Northstar Events'] },
  { label: 'Negociación', color: '#44c5a4', count: 2, value: '12.400 €', cards: ['Lumen Brand'] },
];

const initialTasks = [
  { text: 'Enviar propuesta revisada a Northstar', meta: 'Hoy · Comercial', priority: 'Alta', done: false },
  { text: 'Confirmar timing con Naranja Weddings', meta: 'Hoy · Producción', priority: 'Alta', done: false },
  { text: 'Pedir showreel actualizado a Ana Beltrán', meta: 'Mañana · Talento', priority: 'Media', done: false },
  { text: 'Revisar depósito del evento Meliá', meta: '12 sep · Finanzas', priority: 'Alta', done: false },
];

function HealthDot({ health }: { health: EventHealth }) {
  return <span className={`health-dot ${health}`} aria-label={health === 'green' ? 'Todo listo' : health === 'orange' ? 'Pendiente' : 'Problema'} />;
}

export default function Home() {
  const [active, setActive] = useState<Section>('Mi día');
  const [tasks, setTasks] = useState(initialTasks);
  const [query, setQuery] = useState('');
  const [showQuickAdd, setShowQuickAdd] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  const filteredEvents = useMemo(() => {
    const needle = query.trim().toLowerCase();
    if (!needle) return events;
    return events.filter((event) => `${event.title} ${event.client} ${event.city}`.toLowerCase().includes(needle));
  }, [query]);

  const completed = tasks.filter((task) => task.done).length;

  return (
    <main className="app-shell">
      <aside className={`sidebar ${menuOpen ? 'open' : ''}`}>
        <div className="brand"><div className="brand-mark">PL</div><div><strong>PERFORMANCE</strong><span>LAB OS</span></div></div>
        <div className="workspace-switcher"><div className="avatar">M</div><div><b>Performance Lab</b><small>Espacio de trabajo</small></div><ChevronDown size={15} /></div>
        <nav className="main-nav" aria-label="Navegación principal">
          <p className="nav-label">Espacio de trabajo</p>
          {nav.map(({ label, icon: Icon }) => <button key={label} className={`nav-item ${active === label ? 'active' : ''}`} onClick={() => { setActive(label); setMenuOpen(false); }}><Icon size={18} strokeWidth={active === label ? 2.4 : 1.8} /><span>{label}</span>{label === 'Tareas' && <em>{tasks.filter((t) => !t.done).length}</em>}</button>)}
          <p className="nav-label second">Recursos</p>
          <button className="nav-item muted" onClick={() => setActive('Propuestas')}><Zap size={18} /><span>Conceptos</span><small>Próximamente</small></button>
          <button className="nav-item muted" onClick={() => setActive('Propuestas')}><CircleDollarSign size={18} /><span>Pagos</span><small>Próximamente</small></button>
        </nav>
        <div className="sidebar-bottom"><button className="nav-item"><Settings size={18} /><span>Configuración</span></button><div className="user-card"><div className="avatar coral">M</div><div><b>Manuel</b><small>Administrador</small></div><button aria-label="Más opciones"><ChevronDown size={14} /></button></div></div>
      </aside>

      <section className="content-area">
        <header className="topbar"><button className="mobile-menu" aria-label="Abrir menú" onClick={() => setMenuOpen(!menuOpen)}><Menu size={22} /></button><div className="crumb"><span>Performance Lab</span><b>/</b><strong>{active}</strong></div><div className="top-actions"><div className="search-wrap"><Search size={17} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Buscar en tu espacio..." aria-label="Buscar" /><kbd>⌘ K</kbd></div><button className="icon-button" aria-label="Notificaciones"><Bell size={18} /><i /></button><div className="top-avatar">M</div></div></header>

        <div className="page-content">
          {active === 'Mi día' ? <>
            <div className="welcome-row"><div><p className="eyebrow">MARTES, 9 DE SEPTIEMBRE DE 2026</p><h1>Buenos días, Manuel <span>✦</span></h1><p className="subhead">Aquí tienes lo que necesita tu atención hoy.</p></div><button className="primary-button" onClick={() => setShowQuickAdd(true)}><Plus size={17} /> Añadir rápido</button></div>

            <div className="metric-grid"><div className="metric-card focus"><div className="metric-icon"><Activity size={18} /></div><div><span className="metric-label">Seguimientos hoy</span><strong>6</strong><small className="positive">2 más que ayer</small></div><div className="metric-spark"><span /><span /><span /><span /><span /><span /><span /></div></div><div className="metric-card"><div className="metric-icon purple"><FileText size={18} /></div><div><span className="metric-label">Propuestas abiertas</span><strong>3</strong><small>31.600 € en juego</small></div><a href="#pipeline">Ver pipeline <ArrowUpRight size={14} /></a></div><div className="metric-card"><div className="metric-icon amber"><CalendarDays size={18} /></div><div><span className="metric-label">Próximos eventos</span><strong>3</strong><small>En los próximos 30 días</small></div><a href="#events">Ver calendario <ArrowUpRight size={14} /></a></div><div className="metric-card"><div className="metric-icon mint"><CircleDollarSign size={18} /></div><div><span className="metric-label">Pendiente de cobro</span><strong>4.250 €</strong><small className="warning">2 depósitos pendientes</small></div><a href="#payments">Revisar pagos <ArrowUpRight size={14} /></a></div></div>

            <div className="two-col"><section className="panel events-panel" id="events"><div className="panel-head"><div><h2>Próximos eventos</h2><p>La producción de las próximas semanas.</p></div><button className="text-button" onClick={() => setActive('Eventos')}>Ver todos <ArrowUpRight size={14} /></button></div><div className="event-list">{filteredEvents.map((event) => <article className="event-row" key={event.id}><div className="event-date"><b>{event.date.split(' ')[0]}</b><span>{event.date.split(' ')[1]}</span></div><div className="event-main"><div className="event-title-row"><h3>{event.title}</h3><span className={`status-pill ${event.status.toLowerCase()}`}>{event.status}</span></div><p>{event.client} <span>·</span> {event.time} · {event.city}</p><div className="event-meta"><span><span className="mini-pin">⌖</span>{event.venue}</span><span className="artist-count"><Users size={13} />{event.artists || '—'} artistas</span></div></div><div className="health"><HealthDot health={event.health} /><span>{event.issue}</span></div><button className="row-more" aria-label={`Abrir ${event.title}`}>•••</button></article>)}</div></section>

              <section className="panel tasks-panel"><div className="panel-head"><div><h2>Tareas prioritarias</h2><p>{completed === tasks.length ? 'Todo completado. Buen trabajo.' : `${tasks.length - completed} pendientes para hoy.`}</p></div><button className="round-add" aria-label="Añadir tarea" onClick={() => setShowQuickAdd(true)}><Plus size={16} /></button></div><div className="task-progress"><span><b>{completed}</b> de {tasks.length} completadas</span><div><i style={{ width: `${(completed / tasks.length) * 100}%` }} /></div></div><div className="task-list">{tasks.map((task, index) => <label className={`task-row ${task.done ? 'done' : ''}`} key={task.text}><button className="task-check" aria-label={task.done ? 'Marcar pendiente' : 'Completar tarea'} onClick={() => setTasks(tasks.map((item, i) => i === index ? { ...item, done: !item.done } : item))}>{task.done && <Check size={13} />}</button><span><b>{task.text}</b><small>{task.meta}</small></span><em className={task.priority.toLowerCase()}>{task.priority}</em></label>)}</div><button className="panel-footer-button" onClick={() => setActive('Tareas')}>Abrir lista de tareas <ArrowUpRight size={14} /></button></section></div>

            <section className="panel pipeline-panel" id="pipeline"><div className="panel-head"><div><h2>Pipeline comercial</h2><p>Una vista rápida de tus oportunidades activas.</p></div><button className="text-button" onClick={() => setActive('Pipeline')}>Abrir pipeline <ArrowUpRight size={14} /></button></div><div className="pipeline-board">{pipeline.map((stage) => <div className="pipeline-stage" key={stage.label}><div className="stage-head"><span><i style={{ background: stage.color }} />{stage.label}</span><b>{stage.count}</b></div><div className="stage-value">{stage.value}</div>{stage.cards.map((card) => <button className="deal-card" key={card} onClick={() => setActive('Clientes')}><span className="deal-dot" style={{ background: stage.color }} />{card}<ArrowUpRight size={13} /></button>)}</div>)}</div></section>

            <div className="bottom-grid"><section className="insight-card"><div className="insight-orb"><Sparkles size={19} /></div><div><p className="eyebrow">LAB INSIGHT</p><h3>3 perfiles de talento necesitan atención</h3><p>Ana Beltrán, Leo Martín y Clara Ruiz están por debajo del 80% de completitud.</p><button onClick={() => setActive('Talento')}>Revisar perfiles <ArrowUpRight size={14} /></button></div></section><section className="quick-card"><div className="quick-title"><h2>Acciones rápidas</h2><span>Atajos</span></div><div className="quick-actions"><button onClick={() => setShowQuickAdd(true)}><Plus size={16} /><span>Nuevo cliente</span><kbd>N C</kbd></button><button onClick={() => setActive('Eventos')}><CalendarDays size={16} /><span>Crear evento</span><kbd>N E</kbd></button><button onClick={() => setActive('Propuestas')}><FileText size={16} /><span>Nueva propuesta</span><kbd>N P</kbd></button></div></section></div>
          </> : active === 'Clientes' ? <ClientsModule query={query} onBack={() => setActive('Mi día')} /> : active === 'Talento' ? <TalentModule query={query} onBack={() => setActive('Mi día')} /> : <ModulePlaceholder section={active} onBack={() => setActive('Mi día')} />}
        </div>
      </section>
      {showQuickAdd && <div className="modal-backdrop" onMouseDown={() => setShowQuickAdd(false)}><div className="quick-modal" onMouseDown={(e) => e.stopPropagation()}><div className="modal-head"><div><p className="eyebrow">ACCIÓN RÁPIDA</p><h2>¿Qué quieres añadir?</h2></div><button className="close-button" onClick={() => setShowQuickAdd(false)} aria-label="Cerrar"><X size={18} /></button></div><div className="quick-modal-grid"><button onClick={() => { setActive('Clientes'); setShowQuickAdd(false); }}><Users size={19} /><b>Cliente</b><span>Guardar una nueva relación comercial</span></button><button onClick={() => { setActive('Eventos'); setShowQuickAdd(false); }}><CalendarDays size={19} /><b>Evento</b><span>Crear una ficha de producción</span></button><button onClick={() => { setActive('Tareas'); setShowQuickAdd(false); }}><Check size={19} /><b>Tarea</b><span>Añadir algo pendiente</span></button><button onClick={() => { setActive('Propuestas'); setShowQuickAdd(false); }}><FileText size={19} /><b>Propuesta</b><span>Preparar una opción para un cliente</span></button></div></div></div>}
    </main>
  );
}

function ClientsModule({ query, onBack }: { query: string; onBack: () => void }) {
  const needle = query.trim().toLowerCase();
  const clients = importedClients.filter((client) => !needle || `${client.name} ${client.contact} ${client.email} ${client.city} ${client.type}`.toLowerCase().includes(needle));
  return <div className="data-module"><div className="module-head"><div><p className="eyebrow">BASE DE DATOS COMERCIAL</p><h1>Clientes</h1><p>{clients.length} relaciones importadas del Excel, ordenadas alfabéticamente.</p></div><button className="primary-button" onClick={onBack}>Volver a Mi día</button></div><div className="data-toolbar"><span>{importedClients.length} clientes</span><span>Fuente: IBIZA_2026_PRO</span></div><div className="data-table-wrap"><table className="data-table"><thead><tr><th>Cliente</th><th>Contacto</th><th>Teléfono</th><th>Email</th><th>Tipo</th><th>Ciudad</th></tr></thead><tbody>{clients.map((client) => <tr key={`${client.name}-${client.email}`}><td><b>{client.name}</b></td><td>{client.contact || '—'}</td><td>{client.phone || '—'}</td><td>{client.email || '—'}</td><td>{client.type || '—'}</td><td>{client.city || '—'}</td></tr>)}</tbody></table></div></div>;
}

function TalentModule({ query, onBack }: { query: string; onBack: () => void }) {
  const needle = query.trim().toLowerCase();
  const artists = importedArtists.filter((artist) => !needle || `${artist.name} ${artist.category} ${artist.subcategory} ${artist.city} ${artist.email}`.toLowerCase().includes(needle));
  return <div className="data-module"><div className="module-head"><div><p className="eyebrow">BASE DE DATOS DE ARTISTAS</p><h1>Artistas</h1><p>{artists.length} perfiles importados. Busca por nombre, disciplina o ciudad.</p></div><button className="primary-button" onClick={onBack}>Volver a Mi día</button></div><div className="artist-stats"><div><b>{importedArtists.length}</b><span>perfiles</span></div><div><b>{importedArtists.filter((a) => a.city.toLowerCase().includes('ibiza')).length}</b><span>con base en Ibiza</span></div><div><b>{importedArtists.filter((a) => a.email).length}</b><span>con email</span></div></div><div className="data-table-wrap"><table className="data-table"><thead><tr><th>Artista</th><th>Disciplina</th><th>Especialidad</th><th>Base</th><th>Teléfono</th><th>Email</th><th>Fee</th></tr></thead><tbody>{artists.map((artist) => <tr key={`${artist.name}-${artist.email}`}><td><b>{artist.name}</b></td><td>{artist.category || '—'}</td><td>{artist.subcategory || '—'}</td><td>{artist.city || '—'}</td><td>{artist.phone || '—'}</td><td>{artist.email || '—'}</td><td>{artist.fee || '—'}</td></tr>)}</tbody></table></div></div>;
}

function ModulePlaceholder({ section, onBack }: { section: Exclude<Section, 'Mi día'>; onBack: () => void }) {
  const content: Record<Exclude<Section, 'Mi día'>, { title: string; text: string; icon: typeof Users; color: string }> = {
    Clientes: { title: 'Clientes', text: 'Tu base de relaciones comerciales estará aquí.', icon: Users, color: 'purple' },
    Pipeline: { title: 'Pipeline comercial', text: 'Gestiona tus oportunidades desde el primer contacto hasta el cierre.', icon: Target, color: 'mint' },
    Eventos: { title: 'Eventos', text: 'El calendario de producciones y sus fichas operativas.', icon: CalendarDays, color: 'amber' },
    Talento: { title: 'Talento', text: 'Perfiles, disciplinas, tarifas y disponibilidad.', icon: Sparkles, color: 'purple' },
    Tareas: { title: 'Tareas', text: 'El trabajo pendiente de todo el equipo, en un solo lugar.', icon: Check, color: 'mint' },
    Propuestas: { title: 'Propuestas', text: 'Crea opciones claras con costes internos separados.', icon: FileText, color: 'amber' },
  };
  const item = content[section]; const Icon = item.icon;
  return <div className="empty-module"><div className={`empty-icon ${item.color}`}><Icon size={27} /></div><p className="eyebrow">MÓDULO EN CONSTRUCCIÓN</p><h1>{item.title}</h1><p>{item.text}</p><span className="coming-pill"><Clock3 size={14} /> Siguiente bloque de la fase 1</span><button className="primary-button" onClick={onBack}>Volver a Mi día</button></div>;
}
